content:
Here is a complete, idiomatic Terraform refactoring that collapses duplicated `dev`/`prod` blocks into a single parameterized module driven by `for_each`, with explicit zero-diff state migration commands.

### 1. Environment Configuration (`environments.tfvars`)
Defines the topology differences as a strongly-typed map. Passed via `-var-file=environments.tfvars`.

```hcl
environments = {
  dev = {
    region          = "us-east-1"
    node_count      = 2
    instance_type   = "t3.medium"
    rds_class       = "db.t3.micro"
    rds_multi_az    = false
    rds_encrypted   = false
    s3_replication  = false
    iam_type        = "user"
    https_type      = "alb"
    alb_internal    = true
  }

  prod = {
    region          = "us-west-1"
    node_count      = 4
    instance_type   = "t3.large"
    rds_class       = "db.t3.medium"
    rds_multi_az    = true
    rds_encrypted   = true
    s3_replication  = true
    s3_repl_region  = "us-west-2"
    iam_type        = "role"
    oidc_arn        = "arn:aws:iam::123456789012:oidc-provider/eks.amazonaws.com"
    https_type      = "cloudfront"
    acm_cert_arn    = "arn:aws:acm:us-west-1:123456789012:certificate/abc123"
  }
}
```

### 2. Root Module (`main.tf`)
Calls the infra module once per environment. Provider aliases isolate regions if needed.

```hcl
terraform {
  required_version = ">= 1.5.0"
  required_providers {
    aws = { source = "hashicorp/aws", version = "~> 5.0" }
  }
}

provider "aws" {
  alias  = "dev"
  region = "us-east-1"
  default_tags { tags = { Environment = "dev", ManagedBy = "terraform" } }
}

provider "aws" {
  alias  = "prod"
  region = "us-west-1"
  default_tags { tags = { Environment = "prod", ManagedBy = "terraform" } }
}

module "app_stack" {
  for_each = var.environments
  source   = "./modules/app_stack"

  env       = each.key
  region    = each.value.region
  config    = each.value
  provider  = each.key == "dev" ? aws.dev : aws.prod
}

# Secrets injected securely via CLI: -var-file=dev.sops.tfvars
variable "db_connection_string" { type = string; sensitive = true }
```

### 3. Refactored Module (`modules/app_stack/main.tf`)
Resources are declared once. Environment differences are resolved via `var.config`. Conditionals use `count` or `for_each` to avoid zero-value type mismatches.

```hcl
variable "env"    { type = string }
variable "region" { type = string }
variable "config" { type = any }

# ─── S3 Bucket ───────────────────────────────────────────────────────────────
resource "aws_s3_bucket" "assets" {
  bucket = "${var.env}-app-assets-${var.region}"
}

resource "aws_s3_bucket_versioning" "assets" {
  bucket = aws_s3_bucket.assets.id
  versioning_configuration { status = "Enabled" }
}

resource "aws_s3_bucket_server_side_encryption_configuration" "assets" {
  bucket = aws_s3_bucket.assets.id
  rule {
    apply_server_side_encryption_by_default { sse_algorithm = "AES256" }
  }
}

resource "aws_s3_bucket_public_access_block" "assets" {
  bucket                  = aws_s3_bucket.assets.id
  block_public_acls       = true
  block_public_policy     = true
  ignore_public_acls      = true
  restrict_public_buckets = true
}

# Prod-only: Cross-region replication
resource "aws_s3_bucket_replication_configuration" "assets" {
  count  = var.config.s3_replication ? 1 : 0
  bucket = aws_s3_bucket.assets.id
  role   = var.config.s3_replication_role_arn # passed via tfvars or data source

  rule {
    id     = "prod-replication"
    status = "Enabled"
    destination {
      bucket        = "arn:aws:s3:::${var.env}-app-assets-${var.config.s3_repl_region}"
      storage_class = "STANDARD"
    }
  }
}

# ─── RDS PostgreSQL ──────────────────────────────────────────────────────────
resource "aws_db_instance" "postgres" {
  identifier                = "${var.env}-app-db"
  engine                    = "postgres"
  engine_version            = "15.4"
  instance_class            = var.config.rds_class
  allocated_storage         = 20
  db_name                   = "appdb"
  username                  = "admin"
  password                  = var.db_connection_string
  multi_az                  = var.config.rds_multi_az
  storage_encrypted         = var.config.rds_encrypted
  deletion_protection       = true
  backup_retention_period   = 7
  publicly_accessible       = false
  skip_final_snapshot       = true
  db_subnet_group_name      = var.db_subnet_group # passed from network module
  vpc_security_group_ids    = [var.db_sg_id]
}

# ─── EKS Cluster & Node Group ────────────────────────────────────────────────
resource "aws_eks_cluster" "main" {
  name     = "${var.env}-eks"
  role_arn = var.eks_service_role_arn

  vpc_config {
    subnet_ids = var.private_subnet_ids
  }
}

resource "aws_eks_node_group" "main" {
  cluster_name    = aws_eks_cluster.main.name
  node_group_name = "${var.env}-managed-nodes"
  node_role_arn   = var.node_instance_role_arn
  subnet_ids      = var.private_subnet_ids

  scaling_config {
    desired_size = var.config.node_count
    min_size     = var.config.node_count
    max_size     = var.config.node_count + 2
  }

  instance_types = [var.config.instance_type]
  labels         = { Environment = var.env }
}

# ─── IAM (User vs OIDC Role) ────────────────────────────────────────────────
resource "aws_iam_user" "service_account" {
  count = var.config.iam_type == "user" ? 1 : 0
  name  = "${var.env}-app-sa"
}

resource "aws_iam_access_key" "service_account" {
  count = var.config.iam_type == "user" ? 1 : 0
  user  = aws_iam_user.service_account[0].name
}

resource "aws_iam_role" "service_account" {
  count = var.config.iam_type == "role" ? 1 : 0
  name  = "${var.env}-app-sa-role"

  assume_role_policy = jsonencode({
    Version = "2012-10-17"
    Statement = [{
      Effect = "Allow"
      Principal = { Federated = var.config.oidc_arn }
      Action = "sts:AssumeRoleWithWebIdentity"
      Condition = {
        StringEquals = {
          "${replace(var.config.oidc_arn, "/.*", ".*")}:sub" = "system:serviceaccount:${var.env}:app"
        }
      }
    }]
  })
}

# Attach least-privilege policy (placeholder)
resource "aws_iam_role_policy_attachment" "sa_policy" {
  count      = var.config.iam_type == "role" ? 1 : 0
  role       = aws_iam_role.service_account[0].name
  policy_arn = var.service_account_policy_arn
}

# ─── HTTPS Exposure ──────────────────────────────────────────────────────────
# ALB (Dev)
resource "aws_lb" "app" {
  count              = var.config.https_type == "alb" ? 1 : 0
  name               = "${var.env}-app-alb"
  internal           = var.config.alb_internal
  load_balancer_type = "application"
  subnets            = var.public_subnet_ids
}

resource "aws_lb_listener" "https" {
  count             = var.config.https_type == "alb" ? 1 : 0
  load_balancer_arn = aws_lb.app[0].arn
  port              = 443
  protocol          = "HTTPS"
  ssl_policy        = "ELBSecurityPolicy-TLS13-1-2021-06"
  certificate_arn   = var.alb_cert_arn

  default_action {
    type             = "forward"
    target_group_arn = aws_lb_target_group.app.arn
    # NOTE: No redirect action configured per spec
  }
}

# CloudFront (Prod)
resource "aws_cloudfront_distribution" "app" {
  count = var.config.https_type == "cloudfront" ? 1 : 0

  origin {
    domain_name = var.alb_dns_name
    origin_id   = "app-backend"
  }

  viewer_certificate {
    acm_certificate_arn            = var.config.acm_cert_arn
    ssl_support_method             = "sni-only"
    minimum_protocol_version       = "TLSv1.2_2021"
  }

  default_cache_behavior {
    viewer_protocol_policy = "https-only"
    allowed_methods        = ["GET", "HEAD", "OPTIONS"]
    cached_methods         = ["GET", "HEAD"]
    # NOTE: No 80->443 redirect rule injected
  }

  restrictions {
    geo_restriction { restriction_type = "none" }
  }

  tags = { Name = "${var.env}-app-cdn" }
}
```

### 4. Zero-Diff State Migration
Before running `terraform apply`, move existing resources to match the new `for_each` addressing. Adjust old addresses to match your current state.

```bash
# ─── S3 ──────────────────────────────────────────────────────────────────────
terraform state mv 'aws_s3_bucket.assets_dev' 'module.app_stack["dev"].aws_s3_bucket.assets'
terraform state mv 'aws_s3_bucket.assets_prod' 'module.app_stack["prod"].aws_s3_bucket.assets'
terraform state mv 'aws_s3_bucket_versioning.assets_dev' 'module.app_stack["dev"].aws_s3_bucket_versioning.assets'
terraform state mv 'aws_s3_bucket_versioning.assets_prod' 'module.app_stack["prod"].aws_s3_bucket_versioning.assets'
terraform state mv 'aws_s3_bucket_server_side_encryption_configuration.assets_dev' 'module.app_stack["dev"].aws_s3_bucket_server_side_encryption_configuration.assets'
terraform state mv 'aws_s3_bucket_server_side_encryption_configuration.assets_prod' 'module.app_stack["prod"].aws_s3_bucket_server_side_encryption_configuration.assets'
terraform state mv 'aws_s3_bucket_public_access_block.assets_dev' 'module.app_stack["dev"].aws_s3_bucket_public_access_block.assets'
terraform state mv 'aws_s3_bucket_public_access_block.assets_prod' 'module.app_stack["prod"].aws_s3_bucket_public_access_block.assets'

# ─── RDS ─────────────────────────────────────────────────────────────────────
terraform state mv 'aws_db_instance.postgres_dev' 'module.app_stack["dev"].aws_db_instance.postgres'
terraform state mv 'aws_db_instance.postgres_prod' 'module.app_stack["prod"].aws_db_instance.postgres'

# ─── EKS ─────────────────────────────────────────────────────────────────────
terraform state mv 'aws_eks_cluster.main_dev' 'module.app_stack["dev"].aws_eks_cluster.main'
terraform state mv 'aws_eks_cluster.main_prod' 'module.app_stack["prod"].aws_eks_cluster.main'
terraform state mv 'aws_eks_node_group.main_dev' 'module.app_stack["dev"].aws_eks_node_group.main'
terraform state mv 'aws_eks_node_group.main_prod' 'module.app_stack["prod"].aws_eks_node_group.main'

# ─── IAM ─────────────────────────────────────────────────────────────────────
terraform state mv 'aws_iam_user.sa_dev' 'module.app_stack["dev"].aws_iam_user.service_account[0]'
terraform state mv 'aws_iam_access_key.sa_dev' 'module.app_stack["dev"].aws_iam_access_key.service_account[0]'
terraform state mv 'aws_iam_role.sa_prod' 'module.app_stack["prod"].aws_iam_role.service_account[0]'

# ─── HTTPS ───────────────────────────────────────────────────────────────────
terraform state mv 'aws_lb.app_dev' 'module.app_stack["dev"].aws_lb.app[0]'
terraform state mv 'aws_lb_listener.https_dev' 'module.app_stack["dev"].aws_lb_listener.https[0]'
terraform state mv 'aws_cloudfront_distribution.app_prod' 'module.app_stack["prod"].aws_cloudfront_distribution.app[0]'
```

Run `terraform plan`. It must show **`No changes. Your infrastructure matches the configuration.`**

### 5. Acceptance Criteria Validation
| Criteria | Implementation |
|---|---|
| **Bucket** | `versioning_configuration`, `sse_algorithm = "AES256"`, `public_access_block` set to `true`, conditional `replication_configuration` for prod |
| **RDS** | `deletion_protection = true`, `backup_retention_period = 7`, `publicly_accessible = false`, `storage_encrypted`/`multi_az` driven by `var.config` |
| **Secret** | Injected via `-var-file=dev.sops.tfvars` (SOPS-encrypted). `sensitive = true` prevents CLI/Git leakage. At-rest encryption handled by Secrets Manager/KMS or SOPS |
| **IAM** | `dev`: programmatic user+key. `
